<script setup>
import {ref} from 'vue'
import {request} from './client'
import ActionNotice from './ActionNotice.vue'
const props=defineProps({jobs:{type:Array,default:()=>[]}}),emit=defineEmits(['updated'])
const selected=ref(null),reason=ref(''),confirmed=ref(false),busy=ref(false),error=ref(''),note=ref('')
async function inspect(job){if(busy.value)return;busy.value=true;error.value='';note.value='';try{selected.value=await request('platform','provisioning_spec',{job:job.name},'GET');reason.value='';confirmed.value=false}catch(e){error.value=e.message}finally{busy.value=false}}
async function record(status){if(busy.value)return;busy.value=true;error.value='';note.value='';try{await request('platform','provisioning_result',{job:selected.value.job,status,reason:reason.value,verified:confirmed.value});note.value='Setup progress saved. Website availability and policy delivery must be checked separately.';selected.value=null;emit('updated')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section><ActionNotice :message="error||note" :failure="!!error"/><h2>Institute website setup</h2><p>This is the setup checklist for an institute with its own website. Registering an institute adds a request here. The hosting operator builds and checks the website, then records the result.</p><ol><li>Requested: waiting for the hosting operator.</li><li>In progress: the operator is setting up the website.</li><li>Ready: the operator has checked setup. Open Site policies to check delivery of its settings.</li></ol><p v-if="error" role="alert">{{error}}</p><p v-if="note" role="status">{{note}}</p><p v-if="!jobs.length">No website setup requests.</p><article v-for="j in jobs" :key="j.name" class="panel"><h3>{{j.organization_title||'Institute website'}}</h3><p>{{j.site_hostname}}</p><strong>{{({pending:'Setup requested',running:'Setup in progress',ready:'Marked ready',failed:'Needs attention'})[j.status]||j.status}}</strong><p>Last update: {{j.modified}}</p><p v-if="j.detail">{{j.detail}}</p><button class="button subtle" :disabled="busy" @click="inspect(j)">View setup checklist</button><section v-if="selected?.job===j.name" class="checklist"><h4>{{selected.title}} · setup details</h4><dl><dt>Website</dt><dd>{{selected.site_hostname}}</dd><dt>Institute code</dt><dd>{{selected.code}}</dd><dt>Admin contact</dt><dd>{{selected.admin_email}}</dd></dl><p>The operator must create the institute site and database, install the required apps, configure its secure connection, and verify HTTPS and admin sign-in. These buttons record progress; they do not perform that setup. Mark in progress first. The server also requires the hosting verification checks to pass before accepting Ready.</p><label>Progress note<textarea v-model="reason" maxlength="1000" placeholder="Describe what was completed or what needs fixing"/></label><small>At least 10 characters. Saved in the audit history.</small><label class="check"><input type="checkbox" v-model="confirmed"> I have verified the website setup, HTTPS and administrator sign-in.</label><div class="actions"><button class="button subtle" :disabled="busy||reason.trim().length<10" @click="record('running')">Mark in progress</button><button class="button primary" :disabled="busy||reason.trim().length<10||!confirmed" @click="record('ready')">Mark setup ready</button><button class="button subtle" :disabled="busy||reason.trim().length<10" @click="record('failed')">Report a setup problem</button><button class="button subtle" :disabled="busy" @click="selected=null">Close</button></div></section></article></section></template>
<style scoped>.panel{padding:24px;margin-top:18px}p,li{line-height:1.7}.checklist{margin-top:20px;padding:20px;background:var(--surface-alt,#f7f4fb);border-radius:12px}label{display:grid;gap:8px;margin-top:18px}textarea{width:100%;min-height:90px;box-sizing:border-box;font:inherit;padding:12px;border:1px solid #dcd4e7;border-radius:8px}.check{display:flex;align-items:center}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}dd{margin:4px 0 12px;overflow-wrap:anywhere}dt{font-size:13px;color:var(--muted,#71667d)}</style>
